#define light 2.*vec3(-1,.8,-1)
vec2 map (vec3 p) {
    float d = 1e4;
    for (float i = 0.; i < 11.; i++) {
        p = abs(p);
        p -= .5*exp2(-i);
        p.xz *= ei(.6);
        p.yz *= ei(.4);
        d = min(d,box(p,vec3(.0006*i*i,.005*exp2(-.5*i),.005*exp2(-.5*i)))-.0001);
    }

    return vec2(d,0.);
}
vec3 normal (vec3 p) {
    vec2 e = vec2(1e-4,0);
    float m = map(p).x;
    return normalize(vec3(
        map(p+e.xyy).x-m,
        map(p+e.yxy).x-m,
        map(p+e.yyx).x-m
    ));

}
